const {computeRatio} = require('./bench/sandbox/compute-ratio-ht.js');
const fs = require('fs'), os = require('os'), path = require('path');

function tmpFile(content) {
  const f = path.join(os.tmpdir(), Math.random().toString(36).slice(2)+'.jsonl');
  fs.writeFileSync(f, content);
  return f;
}

// Example 1
const on1 = tmpFile([
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":100,\"output_tokens\":50,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}',
  '{\"role\":\"assistant\",\"usage\":{\"input_tokens\":80,\"output_tokens\":30,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}'
].join('\n'));
const off1 = tmpFile('{\"role\":\"assistant\",\"usage\":{\"input_tokens\":200,\"output_tokens\":100,\"cache_read_input_tokens\":0,\"cache_creation_input_tokens\":0}}');
console.log('Ex1:', computeRatio(on1, off1));

